Tools: [{"type": "function", "function": {"name": "analyze_customer_feedback", "description": "Analyzes a batch of customer feedback to determine sentiment, extract key phrases, and identify action items or questions.", "parameters": {"type": "object", "properties": {"feedback_batch": {"type": "array", "description": "A batch of customer feedback text to be analyzed.", "items": {"type": "string"}}}, "required": ["feedback_batch"]}}}, {"type": "function", "function": {"name": "extract_sentiment", "description": "Determines the sentiment of a given text as positive, negative, or neutral.", "parameters": {"type": "object", "properties": {"text": {"type": "string", "description": "The text to analyze for sentiment."}}, "required": ["text"]}}}, {"type": "function", "function": {"name": "extract_key_phrases", "description": "Extracts key phrases from a given text to identify the main concepts.", "parameters": {"type": "object", "properties": {"text": {"type": "string", "description": "The text from which to extract key phrases."}}, "required": ["text"]}}}, {"type": "function", "function": {"name": "identify_action_items", "description": "Identifies action items or questions within a given text that may require follow-up.", "parameters": {"type": "object", "properties": {"text": {"type": "string", "description": "The text to be analyzed for action items or questions."}}, "required": ["text"]}}}]\nExample: <tool_call>
{"name": "analyze_customer_feedback", "arguments": {"feedback_batch": ["I love the new update, it has made the app much more user-friendly!", "The customer service was disappointing, I waited for hours but no resolution was provided.", "Is there an option to export my data in a CSV format?", "The latest feature is quite buggy and causes the app to crash frequently."]}}
</tool_call>

Tools: [{"type": "function", "function": {"name": "ExpertQAExtractor", "description": "Extracts a list of questions that ask for clarification on an ambiguous or unclear statement in the document. These help resolve confusion.", "parameters": {"type": "object", "properties": {"clarification_questions": {"type": "array", "items": {"type": "string"}}}, "required": ["clarification_questions"]}}}]\nExample: <tool_call>
