Tools: [{"type": "function", "function": {"name": "find_coding_app", "description": "Finds a coding app based on the specified programming language, user level, and desired features.", "parameters": {"type": "object", "properties": {"language": {"type": "string", "description": "The programming language to learn.", "enum": [null]}, "level": {"type": "string", "description": "The user's experience level with programming.", "enum": ["beginner", "intermediate", "advanced"]}, "features": {"type": "array", "description": "List of desired features in the coding app.", "items": {"type": "string"}}}, "required": ["language", "level", "features"]}}}, {"type": "function", "function": {"name": "get_app_details", "description": "Retrieves detailed information about a specific coding app, including supported platforms and user reviews.", "parameters": {"type": "object", "properties": {"app_name": {"type": "string", "description": "The name of the coding app to retrieve details for.", "enum": [null]}}, "required": ["app_name"]}}}, {"type": "function", "function": {"name": "compare_coding_apps", "description": "Compares multiple coding apps based on features, user reviews, and supported programming languages.", "parameters": {"type": "object", "properties": {"apps": {"type": "array", "description": "A list of coding app names to compare.", "items": {"type": "string"}}, "criteria": {"type": "array", "description": "The criteria to compare the apps by.", "items": {"type": "string"}}}, "required": ["apps", "criteria"]}}}, {"type": "function", "function": {"name": "list_supported_languages", "description": "Lists all programming languages supported by a given coding app.", "parameters": {"type": "object", "properties": {"app_name": {"type": "string", "description": "The name of the coding app.", "enum": [null]}}, "required": ["app_name"]}}}, {"type": "function", "function": {"name": "get_tutorial_recommendations", "description": "Provides a list of recommended tutorials based on the user's selected programming language and experience level.", "parameters": {"type": "object", "properties": {"language": {"type": "string", "description": "The programming language to find tutorials for.", "enum": [null]}, "level": {"type": "string", "description": "The user's experience level.", "enum": ["beginner", "intermediate", "advanced"]}}, "required": ["language", "level"]}}}]\nExample: <tool_call>
