Tools: [{"type": "function", "function": {"name": "extract_insights_from_reports", "description": "Extracts key insights from a collection of project reports in PDF format.", "parameters": {"type": "object", "properties": {"report_files": {"type": "string", "description": "A zip file containing the project reports from which insights need to be extracted."}}, "required": ["report_files"]}}}, {"type": "function", "function": {"name": "compile_knowledge_base", "description": "Compiles extracted insights into a central knowledge base.", "parameters": {"type": "object", "properties": {"extracted_insights": {"type": "string", "description": "A JSON file containing the extracted insights from the project reports."}}, "required": ["extracted_insights"]}}}, {"type": "function", "function": {"name": "notify_team_leads", "description": "Sends notifications to team leads via email when new insights are added to the knowledge base.", "parameters": {"type": "object", "properties": {"knowledge_base_update": {"type": "string", "description": "A JSON file containing the updates made to the knowledge base."}, "team_leads_emails": {"type": "string", "description": "A CSV file containing the email addresses of the team leads to be notified."}}, "required": ["knowledge_base_update", "team_leads_emails"]}}}]\nExample: तपाईंको अनुरोध अनुसार, ज्ञान साझेदारी प्रक्रियालाई स्वचालित गर्नका लागि आवश्यक फङ्क्सन कलहरू निम्न अनुसार कार्यान्वयन गरिनेछ:

<tool_call>
{"name": "extract_insights_from_reports", "arguments": {"report_files": "project_reports.zip"}}
