Tools: [{"type": "function", "function": {"name": "searchEventsByCategory", "description": "Search for events in a specific location and categories within a date range.", "parameters": {"type": "object", "properties": {"location": {"type": "string", "description": "The city or area where the events are to be searched."}, "categories": {"type": "array", "description": "List of event categories to filter the search.", "items": {"type": "string"}}, "dateRange": {"type": "object", "description": "The range of dates to search for events.", "properties": {"start": {"type": "string", "description": "The start date in YYYY-MM-DD format."}, "end": {"type": "string", "description": "The end date in YYYY-MM-DD format."}}, "required": ["start", "end"]}}, "required": ["location", "categories", "dateRange"]}}}, {"type": "function", "function": {"name": "getEventDetails", "description": "Retrieve detailed information about a specific event by its ID.", "parameters": {"type": "object", "properties": {"eventId": {"type": "string", "description": "The unique identifier of the event."}}, "required": ["eventId"]}}}, {"type": "function", "function": {"name": "bookmarkEvent", "description": "Save an event to the user's list of bookmarked events.", "parameters": {"type": "object", "properties": {"eventId": {"type": "string", "description": "The unique identifier of the event to bookmark."}, "userId": {"type": "string", "description": "The unique identifier of the user."}}, "required": ["eventId", "userId"]}}}, {"type": "function", "function": {"name": "registerForEvent", "description": "Register the user for an event using the event's ID.", "parameters": {"type": "object", "properties": {"eventId": {"type": "string", "description": "The unique identifier of the event to register for."}, "userId": {"type": "string", "description": "The unique identifier of the user."}}, "required": ["eventId", "userId"]}}}]\nExample: <tool_call>
